import {S,P,T,D,C,U,refs,motivation} from './model.mjs';
export default [
S('Работа приложения, API, сервер и инфраструктура','Путь одного действия через браузер, обработку и хранение',P(['Обмен','Запрос и ответ в согласованном формате'],['Обработка','Пользователь, проверки, сохранение'],['Запуск','Рабочая среда и выпуск версии']),
'На третьем вебинаре проследим, как действие Анны превращается в сохранённую заявку. Разберём обмен между браузером и сервером, согласуем программный интерфейс и увидим работу с базой. Затем рассмотрим размещение и выпуск версии. Все запросы и результаты заранее подготовлены; запускать программы в эфире не потребуется.',
'Сохраняем роли, поля и номера. Анна — пользователь двенадцать, проект — семнадцать, созданная заявка — сто четыре. Это позволит читать технические фрагменты как продолжение знакомого сценария.','Краткое введение, без повторного определения всех объектов.'),
S('Действие в браузере','Нажатие начинает обмен, но не подтверждает сохранение',U('Заполненная форма заявки','filled',{kind:'form',description:'Проект 17 и согласованная мотивация готовы к передаче; запись заявки ещё не подтверждена.'}),
'Анна нажимает «Подать заявку». Браузер собирает выбранный проект и мотивационный текст в обращение к серверу. Личность не передаётся как свободное поле формы: она определяется по действующему сеансу. На этом шаге ещё нет доказательства сохранения. Интерфейс переходит в ожидание, а сервер должен получить данные и проверить правила. Мы разложим путь на отдельные события, чтобы не смешивать причину, действие и результат.',
'Если браузер мгновенно показал успех без ответа, он мог сообщить ложный результат. Если он повторно отправил форму при задержке, возникла новая попытка обработки. Поэтому состояние кнопки и правило уникальности выполняют разные задачи. В техническом разборе будем каждый раз уточнять, какая часть системы уже знает результат и какой факт она может честно подтвердить. Это особенно важно при обрыве связи после сохранения.','Укажите на действие и подготовленные данные формы.'),
S('Ответственность браузера','Показать состояние и передать пользовательские данные',P(['Подготовка','Получить выбранный проект и мотивацию'],['Отправка','Передать согласованное обращение'],['Представление','Показать ожидание, результат или неопределённость']),
'Браузерная часть управляет представлением и взаимодействием. Она помогает Анне заполнить форму и передаёт обращение в согласованном формате. Затем читает результат и выбирает соответствующее состояние интерфейса. Это не означает право назначить student_id или итоговый статус. Клиентские данные могут быть изменены, а локальные сведения о проекте — устареть. Поэтому сервер не считает внешний вид страницы доказательством допустимости операции.',
'Такое разделение полезно и при разработке. Изменение расположения поля не должно менять правило допустимой длины. Замена интерфейса не должна открывать дополнительные права. Серверный договор позволяет нескольким представлениям обращаться к одной логике. В нашем примере реализуется только согласованный веб-путь, но принцип объясняет, почему правила не прячут исключительно в код кнопки. Дальше посмотрим на сторону, которая принимает окончательное решение.','Не передавайте браузеру полномочие выбрать пользователя.'),
S('Ответственность сервера','Проверки предшествуют изменению данных',P(['Установить пользователя','Получить Анну из действующего сеанса'],['Проверить','Формат, роль, проект, текст и повтор'],['Сохранить','Создать согласованную запись'],['Ответить','Сообщить подтверждённый результат']),
'Сервер принимает запрос и применяет правила независимо от состояния страницы. Он определяет пользователя по сеансу, проверяет структуру данных и право выполнить действие. Для создания заявки нужен студент, открытый существующий проект, допустимая мотивация и отсутствие предыдущей пары. Затем сервер организует сохранение. Только после подтверждения записи можно формировать успешный результат. Такой порядок исключает обещание действия, которое ещё не завершилось.',
'На схеме показаны логические шаги, а не обязательное число функций в программе. Реализация может распределить их между несколькими частями. Существенно, чтобы проверки не исчезли и чтобы ошибка ограничения данных превратилась в понятный договорённый ответ. Если два обращения пришли почти одновременно, простое предварительное чтение ещё не гарантирует отсутствие повтора. Этот случай позже разберём на временной последовательности.','Сначала пользователь и проверки, затем сохранение и ответ.'),
S('Роль базы в обмене','Сохранённое состояние переживает завершение запроса',D(['Браузер Анны','Сервер приложения','База данных'],[['Браузер Анны','Сервер приложения','Запрос на подачу'],['Сервер приложения','База данных','Добавление заявки после проверок'],['База данных','Сервер приложения','Подтверждение сохранения'],['Сервер приложения','Браузер Анны','Ответ с номером 104']]),
'База сохраняет состояние, к которому приложение сможет обратиться после завершения текущего обмена. Сервер получает подтверждение записи и затем сообщает результат браузеру. Позднее Анна открывает свои заявки, а Ирина — обращения проекта. Оба чтения опираются на сохранённую запись. Мы не передаём заявку напрямую из окна Анны в окно Ирины и не требуем одновременного присутствия участников. Именно общий ресурс связывает их действия во времени.',
'На схеме четыре подписанные связи. Их порядок объясняет важный отказ: ответ может потеряться после того, как база уже сохранила запись. Следовательно, повторное чтение является отдельным способом узнать результат. База не управляет пользовательским сообщением напрямую. Сервер получает сведения, а браузер представляет их в соответствии с договором. Дальше введём формат, на котором эти части общаются.','Пройдите путь туда и обратно, начиная слева.'),
S('HTTP','Правила запроса и ответа между участниками веб-обмена',C('HTTP','GET /api/projects\nAccept: application/json','Упрощённая запись запроса каталога. Версия протокола и технические заголовки опущены.'),
'Эйч-ти-ти-пи, HTTP, расшифровывается как Hypertext Transfer Protocol. Это протокол, то есть согласованные правила обмена. Клиент отправляет запрос, сервер возвращает ответ. Запрос указывает операцию и адрес, а при необходимости содержит данные. Ответ содержит код результата и может передавать представление ресурса. Наш фрагмент сокращён, чтобы показать смысл основных частей. Он не является полным сетевым пакетом и не требует ручного ввода.',
'Метод GET в этом примере запрашивает каталог. Адрес /api/projects обозначает согласованный путь нашей системы. Заголовок Accept показывает предпочтительный формат ответа. HTTP не определяет, как именно устроена таблица проектов или какой интерфейс увидит Анна. Эти решения принадлежат приложению. Протокол даёт общий язык обмена, на котором можно выразить наш проектный договор.','HTTP — «эйч-ти-ти-пи», GET — «гет».',[refs.http]),
S('Адрес запроса','Путь обозначает ресурс внутри приложения',T(['Часть адреса','Учебный пример','Смысл'],[['Схема','https','Защищённое соединение'],['Имя узла','projects.example.test','Условный адрес приложения'],['Путь','/api/projects/17','Проект 17'],['Полный пример','https://projects.example.test/api/projects/17','Не является действующим сервисом']]),
'Адрес запроса состоит из частей. Схема задаёт способ обращения, имя узла помогает найти нужный сервис, путь указывает ресурс внутри приложения. В нашем примере projects.example.test является условным доменом для пояснения. К нему не нужно переходить. В рабочих примерах далее будем показывать только путь, потому что обсуждаем договор приложения. Число семнадцать в пути выбирает конкретный проект из общего набора.',
'Адрес сам по себе не выражает все полномочия. Человек может узнать или изменить число в строке, поэтому сервер проверяет право при каждом защищённом действии. Мы также не выводим из одного технического пути обязательный вид страницы. Карточка проекта может использовать сведения этого ресурса и показывать их понятным образом. Следующий слайд добавит к адресу метод, который уточняет намерение обращения.','example.test — условное имя; не открывайте его.',[refs.http]),
S('Метод запроса','GET, POST и PATCH выражают разные действия',T(['Метод','В нашем договоре','Пример'],[['GET','Получить сведения','/api/projects'],['POST','Создать заявку','/api/applications'],['PATCH','Частично изменить заявку','/api/applications/104']]),
'Метод — часть запроса, которая задаёт характер действия. GET используем для получения сведений. POST в нашем договоре создаёт заявку. PATCH передаёт частичное изменение, в данном случае решение по статусу. Эти значения не выводятся только из названия кнопки. Они должны быть согласованы между клиентом и сервером. Если действие меняет данные, нельзя проектировать его как обычное чтение только ради удобства ссылки.',
'При этом протокол не превращает любой POST автоматически в создание именно заявки. Конкретную операцию определяет договор приложения вместе с путём и форматом. Для PATCH также необходимо описать, какие изменения разрешены. В нашем примере не допускается произвольная правка студента, проекта и мотивации через маршрут решения. Передаётся только итоговый статус из согласованного набора. Остальные условия проверяются сервером.','POST — «пост», PATCH — «патч».',[refs.http,refs.patch]),
S('Заголовки','Служебные сведения помогают интерпретировать сообщение',C('HTTP','Content-Type: application/json\nAccept: application/json','Content-Type описывает передаваемое содержимое. Accept задаёт предпочтительный формат ответа.'),
'Заголовки передают сведения о сообщении и условиях обмена. Content-Type сообщает, как понимать тело запроса или ответа. Значение application/json обозначает формат JSON, который скоро разберём. Accept выражает предпочтение клиента по представлению результата. Эти заголовки имеют разное назначение, хотя в примере значения одинаковы. Заголовок не является произвольной строкой для декоративного комментария; его смысл задан правилами обмена.',
'В упрощённых фрагментах механизм сеанса не показан. Это не означает отсутствие входа. Мы заранее считаем его действующим и отдельно объясняем, что сервер получает пользователя из доверенного контекста. Пропущенные технические детали отмечаются, чтобы ведущий не принимал короткую запись за полный набор необходимых сведений. На экране достаточно двух строк для понимания формата передаваемых данных и ожидаемого результата.','Произнесите «контент-тайп», затем объясните смысл по-русски.',[refs.http]),
S('Тело запроса','Передаются выбранный проект и мотивация',C('JSON',JSON.stringify({project_id:17,motivation},null,2),'Тело создания заявки. student_id и status клиент не задаёт.'),
'Тело содержит данные для конкретного действия. При создании заявки Анна передаёт выбранный проект и мотивацию. Поля student_id нет: пользователь определяется сервером. Поля status тоже нет: начальное состояние задаётся по правилу создания. Такой договор уменьшает неоднозначность и не даёт клиенту выбирать полномочия через обычное содержимое формы. Число семнадцать совпадает с карточкой, а мотивация — с подготовленным текстом.',
'Если в запрос неожиданно добавили status со значением accepted, обработка не должна принять его как разрешение на одобрение. Для учебного договора неизвестные поля отклоняются как неподдерживаемое содержимое. Решение преподавателя выполняется отдельной операцией и с отдельной проверкой права. Это разделение помогает понять, почему модель хранения может содержать больше полей, чем клиент передаёт при создании объекта.','Сравните тело с полным составом сохранённой заявки.'),
S('Ответ сервера','Код и содержимое описывают результат операции',C('HTTP + JSON','201 Created\nLocation: /api/applications/104\nContent-Type: application/json\n\n{"id":104,"project_id":17,\n "student_id":12,"status":"pending"}','Сокращённый пример успешного ответа после сохранения.'),
'В ответе сервер сообщает результат. Код двести один, Created, означает создание ресурса. Заголовок Location указывает его идентификатор в адресном виде. В теле кратко показаны номер заявки, проект, студент и начальный статус. Это сокращённое представление: мотивация и время не исчезли из сохранённых данных. Мы опустили их ради читаемости. Успех отправляется после подтверждения сохранения, а не после одного получения текста запроса.',
'Указанный Location не добавляет в учебный договор новую обязательную операцию чтения по этому адресу. Согласованный способ Анны проверить свои обращения — GET /api/my/applications. Адрес созданного ресурса и перечень поддержанных операций являются связанными, но разными частями договора. Такое уточнение сохраняет исходный набор маршрутов и не заставляет ведущего придумывать неописанный запрос.','Created — «криэйтид»; проговорите, что ответ сокращён.',[refs.http]),
S('Формат JSON','Имена полей и значения образуют структуру данных',T(['Фрагмент','Тип','Смысл'],[['"project_id": 17','Число','Идентификатор выбранного проекта'],['"motivation": "..."','Строка','Текст из формы'],['"is_open": true','Логическое значение','Признак открытого набора']]),
'Джей-сон, JSON, расшифровывается как JavaScript Object Notation. Это текстовый формат представления структурированных данных. Имя поля записывается строкой в двойных кавычках, затем идёт двоеточие и значение. Число и логический признак отличаются от строки. Фигурные скобки группируют поля объекта, квадратные могут обозначать массив. Формат не ограничивает обмен одним языком программирования, несмотря на историю названия.',
'В примерах важно сохранять точные имена. project_id и projectId были бы разными именами, если договор не описал преобразование. Мы используем единый вариант с подчёркиванием. JSON задаёт форму записи, но не проверяет, существует ли проект и допустима ли мотивация. Корректно разобранный текст ещё должен пройти правила приложения. Поэтому следующий шаг — различить группы результатов и конкретные причины отказа.','JSON — «джей-сон». Не читайте знаки пунктуации без необходимости.',[refs.json]),
S('Группы результатов','Успех, отказ по запросу и сбой обработки различаются',T(['Код','Значение в нашем договоре'],[['200 / 201','Успешное чтение или создание'],['401 / 403','Вход не подтверждён или действие запрещено'],['409','Конфликт: повтор, закрытый проект, недопустимый переход'],['422','Формат понятен, содержимое не соответствует правилам'],['5xx','Сервер не смог нормально выполнить обработку']]),
'Код ответа помогает клиенту понять общий характер результата. Двухсотые коды связаны с успешной обработкой. Четырёхсотые указывают на условия запроса или его допустимость. Пятисотые относятся к сбою серверной обработки. Конкретное значение читают по стандарту и договору. Для нашего сервиса повторная заявка получает 409, а недопустимая длина — 422. Коды не заменяют понятный текст и машинное обозначение причины.',
'Отсутствие ответа отличается от любого полученного кода. При обрыве нельзя автоматически предположить 500 или отказ в создании. Браузер должен сохранить неопределённость и проверить доступные сведения позже. Также один код 409 может иметь несколько причин в нашем договоре, поэтому тело ошибки содержит отдельный code. Это позволит показать правильное сообщение без угадывания по свободной фразе.','Не называйте сетевой обрыв полученным кодом ответа.',[refs.http]),
S('API как договор','Операция включает путь, данные, права и результат',P(['Обращение','Метод, путь и допустимое содержимое'],['Условия','Кто вызывает и какие правила выполнены'],['Результат','Успешное представление или согласованная ошибка']),
'Эй-пи-ай, API, означает application programming interface, программный интерфейс приложения. В нашем разборе это договор обмена между браузером и сервером. Он описывает операции, форматы, условия доступа и результаты. Перечня адресов недостаточно. Клиенту нужно знать, что передавать и как понять ответ. Серверу — какие правила применить. Договор позволяет создавать части приложения согласованно, даже если их реализуют отдельно.',
'Мы фиксируем шесть операций из исходного плана. Их имена не меняются на следующих слайдах. Если понадобится расширение, оно будет объявлено отдельно. Это особенно важно для «моих заявок»: сервер получает текущего пользователя из сеанса, а не требует student_id в свободной строке. На следующих слайдах пройдём каждую операцию и покажем её связь с экраном и моделью данных.','API — «эй-пи-ай», дайте расшифровку перед сокращением.'),
S('Получение каталога','GET /api/projects возвращает проекты',C('HTTP + JSON','GET /api/projects\n\n200 OK\n[{"id":17,"title":"Сайт студенческого клуба",\n  "teacher_id":7,"is_open":true}]','Сокращённое представление каталога, без полного описания каждого проекта.'),
'Каталог запрашивает набор проектов. Метод GET не создаёт заявку и не меняет её статус. В сокращённом ответе показан один учебный проект. Массив может содержать несколько элементов или быть пустым. Каждая карточка строится из собственных данных. Показанный номер связывает выбор с последующим запросом конкретного проекта. Мы не добавляем в ответ мотивации студентов, потому что они относятся к другому ресурсу и не нужны для выбора темы.',
'Пустой успешный массив отличается от ошибки загрузки. При пустом каталоге интерфейс сообщает отсутствие доступных записей. При неудачном обмене он не должен утверждать, что проектов нет. Такое различие мы уже видели в состояниях интерфейса. Теперь у него появился технический источник: полученный результат и его содержимое. Сокращение ответа отмечено, чтобы модель проекта сохраняла поле description, хотя здесь оно опущено.','Сопоставьте массив с карточками каталога.'),
S('Получение проекта','GET /api/projects/17 возвращает выбранное описание',C('HTTP + JSON','GET /api/projects/17\n\n200 OK\n{"id":17,"title":"Сайт студенческого клуба",\n "description":"Каталог мероприятий и личный кабинет",\n "teacher_id":7,"is_open":true}','Данные для карточки выбранного проекта.'),
'Запрос конкретного проекта содержит идентификатор в пути. Ответ даёт сведения для карточки: название, описание, ответственного и доступность набора. Номер должен совпадать с тем, который Анна выбрала в каталоге. Если проект не найден, нельзя подставлять случайную карточку или показывать форму без контекста. Для учебного договора отсутствие ресурса обозначаем 404. Это отдельная ситуация от закрытого набора, при котором проект существует, но не принимает новые заявки.',
'Полученный is_open описывает состояние на момент чтения. До подачи оно может измениться. Поэтому сервер снова проверит проект при POST. Карточка помогает человеку принять решение, но её копия не даёт бессрочного разрешения на создание. Такая связь чтения и действия показывает, почему договор операции включает текущие условия, а не только поля. Следующий слайд перейдёт к созданию заявки.','Отличите отсутствующий проект от существующего закрытого.'),
S('Создание заявки','POST /api/applications принимает только проект и мотивацию',C('HTTP + JSON',`POST /api/applications\nContent-Type: application/json\n\n${JSON.stringify({project_id:17,motivation},null,2)}`,'Упрощённый запрос. Действующий сеанс подразумевается, технические заголовки опущены.'),
'Эта операция создаёт новую заявку при выполненных условиях. Тело содержит project_id и motivation. Сервер определит Анну как пользователя двенадцать и назначит pending. Именно поэтому клиент не выбирает status и не присылает student_id как источник полномочия. Проект семнадцать должен существовать и быть открыт. До обработки у Анны не должно быть заявки на эту же тему. Все эти условия относятся к одному действию, хотя проверяются на разных уровнях.',
'Успешный ответ получит 201 и номер сто четыре. Для повтора договор предусматривает 409 с кодом APPLICATION_EXISTS. При слишком короткой мотивации будет 422. Этот набор позволяет интерфейсу выбрать конкретное состояние. Мы не отправляем одновременно два показанных успешных запроса для одного студента и проекта: последующие примеры используют разные исходные условия или обозначены как повторная попытка.','Чётко назовите исходное отсутствие заявки.',[refs.http]),
S('Получение своих заявок','GET /api/my/applications использует текущего пользователя',C('HTTP + JSON','GET /api/my/applications\n\n200 OK\n[{"id":104,"project_id":17,\n  "student_id":12,"status":"pending"}]','Сокращённый ответ для Анны. Отбор по текущему пользователю выполняет сервер.'),
'Слово my в маршруте означает текущего установленного пользователя. Анна не должна передавать номер другого студента, чтобы выбрать чужие обращения. Сервер определяет её по сеансу и ограничивает выборку. В ответе показана созданная заявка сто четыре. Полный интерфейс может дополнительно получить название проекта и дату из согласованного представления. Здесь они опущены ради основной связи между пользователем и строкой.',
'После неопределённого результата подачи этот запрос помогает узнать, существует ли обращение. Если запись видна, интерфейс показывает её вместо новой попытки создания. Если запрос чтения тоже не получил ответ, неопределённость сохраняется. Нельзя считать пустым список, который не удалось загрузить. Такой подход связывает пользовательское восстановление с обычной операцией чтения, не вводя неописанный дополнительный маршрут для проверки.','my — «май», объясните значение «текущий пользователь».'),
S('Получение заявок проекта','GET /api/projects/17/applications требует права на проект',C('HTTP + JSON','GET /api/projects/17/applications\n\n200 OK\n[{"id":104,"project_id":17,"student_id":12,\n  "status":"pending"}]','Сокращённый ответ Ирине, чей id 7 совпадает с teacher_id проекта.'),
'Ирина получает обращения к проекту семнадцать. Перед выдачей сервер проверяет её роль и принадлежность проекта. Одного знания адреса недостаточно. Номер проекта доступен в каталоге, поэтому сам путь нельзя считать секретом. Условие teacher_id равно текущему пользователю связывает операцию с матрицей прав. Анна не получает этот список через обычный студенческий доступ, хотя её собственная заявка присутствует среди строк.',
'Ответ может быть пустым, если проект существует, принадлежит Ирине и обращений ещё нет. Это нормальный результат, отличный от запрета доступа. В учебном договоре при недостаточных полномочиях возвращается 403. Интерфейс должен сообщить отказ, а не показать пустой список как будто заявок нет. Такая точность помогает и пользователю, и сопровождению отличать разные причины отсутствия содержимого.','Сначала право Ирины, затем чтение заявок.'),
S('Решение по заявке','PATCH /api/applications/104 меняет только допустимый статус',C('HTTP + JSON','PATCH /api/applications/104\nContent-Type: application/json\n\n{"status":"accepted"}\n\n200 OK\n{"id":104,"status":"accepted"}','Сокращённый пример. Ирина отвечает за проект, исходный статус заявки — pending.'),
'Ирина отправляет частичное изменение заявки сто четыре. В теле только итоговый статус accepted. Для отрицательного решения используется rejected. Сервер по самой заявке получает проект и проверяет, что он принадлежит Ирине. Также проверяется исходное pending. Иначе уже принятое решение нельзя молча заменить. Успешный ответ показывает сохранённый итог. На экране Анны он будет представлен словом «Одобрена».',
'Этот маршрут не является универсальным редактором всех полей заявки. Он не разрешает менять student_id, project_id или мотивацию. Такой объём операции явно ограничен учебным договором. Если статус уже итоговый, возвращается 409 с причиной недопустимого перехода. Если исполнитель не имеет права, возвращается 403. Разделение ошибок позволяет понять, связана ли проблема с состоянием объекта или полномочием пользователя.','PATCH — частичное изменение, а не новая заявка.',[refs.patch]),
S('Единый формат ошибок','Машинный код причины и текст выполняют разные задачи',C('HTTP + JSON','409 Conflict\nContent-Type: application/json\n\n{"code":"APPLICATION_EXISTS",\n "message":"Вы уже подали заявку на этот проект."}','Тело ошибки содержит устойчивый code и понятное пользователю message.'),
'В договоре ошибки имеют единый вид. Поле code помогает программе различить причину без анализа свободной фразы. Поле message даёт человеку понятное объяснение. Текст можно редакционно уточнить, сохранив машинное обозначение. Для повтора используем APPLICATION_EXISTS. Закрытый проект получит PROJECT_CLOSED, недопустимый итоговый переход — INVALID_TRANSITION. Длина мотивации относится к ответу 422 и коду MOTIVATION_LENGTH. Это наши договорённости, а не универсальные имена стандарта HTTP.',
'Согласованность формата уменьшает число особых случаев в интерфейсе. Однако чувствительные внутренние подробности не нужно превращать в пользовательское сообщение. Номер таблицы или текст неожиданной ошибки базы не объясняет Анне дальнейшее действие. Сервер сохраняет технические сведения для разбора, а клиент получает предусмотренную причину. Теперь перейдём от внешнего договора к шагам внутренней обработки.','APPLICATION_EXISTS читается как «заявка уже существует».',[refs.http]),
S('Серверный обработчик','Упорядоченный алгоритм выполняет одну операцию',C('Псевдокод','пользователь = определить_по_сеансу()\nпроверить_вход_и_роль(пользователь)\nданные = разобрать_и_проверить_тело()\nпроверить_проект_и_мотивацию(данные)\nзаявка = сохранить_без_повтора(пользователь, данные)\nвернуть_подтверждение(заявка)','Псевдокод создания заявки: обозначает смысл шагов, а не синтаксис языка.'),
'Обработчик — часть серверной программы, которая принимает конкретную операцию и формирует её результат. На экране псевдокод, то есть описание алгоритма понятными действиями без привязки к языку. Сначала устанавливается пользователь, затем проверяются вход и роль. После разбора данных проверяют проект и мотивацию. Сохранение должно учитывать повтор, а ответ — подтверждённый результат. Каждый шаг соответствует уже известному правилу.',
'Псевдокод не скрывает необходимость обработки отказа. Если условие не выполнено, путь создания прекращается и формируется согласованная ошибка. Порядок отдельных независимых проверок может отличаться в реализации, но нельзя сохранить недопустимую заявку и только потом обнаружить запрет. Мы будем читать алгоритм по смыслу, не требуя от ведущего объяснять незнакомый язык или запускать этот фрагмент.','Сначала объявите псевдокод. Не вводите его в редактор.'),
S('Определение пользователя','Сервер связывает запрос с действующим сеансом',T(['Источник','Можно считать доказательством личности?','Почему'],[['Доверенный контекст сеанса','Да, в принятом учебном допущении','Вход уже проверен системой'],['Поле student_id в JSON','Нет','Клиент может изменить значение'],['Имя на картинке формы','Нет','Внешний вид не устанавливает пользователя']]),
'Аутентификация — установление того, кто обращается к системе. В нашем сценарии она уже выполнена механизмом входа. Обработчик получает доверенный контекст и определяет Анну как пользователя двенадцать. Если в JSON прислали номер семь, это не делает клиента Ириной. Поэтому student_id не входит в согласованное тело создания. Сервер берёт значение из установленного пользователя. Так запрос нельзя превратить в чужую заявку простой подстановкой поля.',
'Мы не проектируем здесь способ выдачи и проверки сеанса. Это явная зависимость учебного примера. Важно понимать её границу: готовый вход позволяет определить пользователя, но не отменяет дальнейшую проверку роли и принадлежности объекта. Человек может быть успешно установлен и всё равно не иметь права на конкретное действие. Следующие слайды разберут эти условия отдельно.','Объясните аутентификацию перед дальнейшим использованием термина.'),
S('Проверка входных данных','Разобранный JSON ещё должен соответствовать договору',T(['Проверка','Корректный вариант','Отказ'],[['Структура','Объект с двумя ожидаемыми полями','Неверное содержимое'],['project_id','Числовой идентификатор проекта','Отсутствует или неподходящий тип'],['motivation','Текст после согласованной нормализации','Нет текста или нарушена длина'],['Лишние поля','Отсутствуют','Не принимаются как полномочие']]),
'Валидация — проверка соответствия данных установленным правилам. Сначала сообщение должно быть корректно разобрано как JSON. Затем проверяется структура: ожидаемые поля, их типы и обязательность. Число проекта и текст мотивации имеют разное назначение. Сервер не обязан превращать любое случайное значение в допустимое. Для учебного договора неподдерживаемое содержимое отклоняется, а неизвестные поля не становятся скрытыми командами.',
'После удаления пробелов с концов мотивация считается по Unicode code points. Это уточнение введено на втором занятии и применяется одинаково. Пятьдесят и тысяча включены в допустимый диапазон. Проверка формата не доказывает существование проекта или право студента. Поэтому техническую допустимость значения отделяем от бизнес-условий. Такой порядок помогает точно назвать причину отказа и сохранить согласованное сообщение интерфейса.','Валидация — проверка данных, а не установление личности.'),
S('Проверка роли','Установленный пользователь получает только разрешённые действия',T(['Операция','Требуемая роль','Пример отказа'],[['Создание заявки','student','Ирина не подаёт заявку как преподаватель'],['Решение по заявке','teacher','Анна не принимает собственную заявку'],['Список проекта','teacher и принадлежность','Роль без связи проекта недостаточна']]),
'Авторизация — проверка права выполнить действие. Она следует после установления пользователя и опирается на роль и объектные условия. В нашем учебном договоре создание заявки предназначено студенту. Решение выполняет преподаватель. Анна может быть успешно вошедшим пользователем, но не вправе одобрить своё обращение. Поэтому отсутствие кнопки в интерфейсе не является достаточной защитой: сервер проверяет роль при обращении.',
'У преподавателя также есть ограничение по собственному проекту. Значение teacher не открывает общий доступ ко всем заявлениям. Таблица помогает различать общий тип действия и конкретный объект. При отсутствии входа используем 401, при установленном пользователе без нужного права — 403. Пользовательское сообщение объясняет отказ без обещания, что повторение того же запроса изменит полномочия.','Авторизация — право действия; сопоставьте с аутентификацией.',[refs.http]),
S('Принадлежность проекта','Ирина принимает решение по связи teacher_id',D(['Заявка 104','Проект 17','teacher_id = 7','Текущая Ирина: id 7'],[['Заявка 104','Проект 17','project_id указывает проект'],['Проект 17','teacher_id = 7','Ответственный'],['teacher_id = 7','Текущая Ирина: id 7','Значения должны совпасть']]),
'Для решения по заявке сначала находят связанный проект. Затем сопоставляют его teacher_id с установленным пользователем. В нашем случае оба значения равны семи, поэтому условие принадлежности выполнено. Другой преподаватель не проходит это условие, даже если знает номер заявки. Клиент не может исправить ситуацию подстановкой teacher_id в тело решения: такого поля там нет, а проверка использует сохранённые связи.',
'Существование объекта и право на него — разные вопросы. Заявка может существовать, но быть недоступной данному пользователю. В учебном договоре защищённая операция возвращает согласованный отказ. Реальные сервисы могут выбирать другую политику раскрытия существования ресурса, но мы не меняем её между примерами. Главное правило остаётся: сервер не выводит полномочие только из знания адреса или роли преподавателя.','Прочитайте цепочку от заявки к проекту и текущему пользователю.'),
S('Бизнес-правила','Допустимость определяется текущим состоянием предметной области',P(['Набор открыт','Проект существует и принимает новые заявки'],['Мотивация допустима','Нормализованный текст имеет 50–1000 символов'],['Повтора нет','Сочетание студента и проекта ещё не занято'],['Переход допустим','Решение применяется только из pending']),
'Бизнес-правила описывают ограничения предметной области, а не синтаксис сообщения. Корректный JSON может содержать закрытый проект. Допустимый номер может ссылаться на уже занятую пару. Правильное слово accepted может прийти для заявки, по которой итог уже сохранён. Поэтому обработка проверяет текущее состояние и контекст операции. Не все правила используются в каждом запросе: открытый набор нужен созданию, а исходный статус — решению.',
'Текущее состояние может измениться между чтением и записью. Это означает, что предварительное условие надо поддержать способом сохранения, а не только отдельным ранним запросом. Для повтора такую защиту даёт уникальная пара. Для перехода можно использовать условное обновление из pending с проверкой результата. Мы не разрабатываем большой код, но явно показываем, какое правило должно оставаться истинным.','Не смешивайте правила создания и решения в одну обязательную форму.'),
S('Обработка отказов','Неправильный путь завершается без недопустимой записи',T(['Причина','Код ответа','Машинная причина'],[['Не подтверждён вход','401','AUTH_REQUIRED'],['Недостаточно прав','403','FORBIDDEN'],['Повтор','409','APPLICATION_EXISTS'],['Проект закрыт','409','PROJECT_CLOSED'],['Длина мотивации','422','MOTIVATION_LENGTH']]),
'Отказ должен сохранять согласованное состояние. Если мотивация короткая, новая заявка не возникает. Если пара занята, существующая запись не дублируется. Если проект закрыт, отказ относится к новой подаче, а не к удалению старых заявок. В таблице закреплены причины и формат результата для наших примеров. Числовые коды соответствуют общей семантике HTTP, машинные имена являются договором именно этого сервиса.',
'Неожиданный технический сбой рассматривается отдельно. Его нельзя выдавать за недопустимую мотивацию или отсутствие права. Подмена причины заставит пользователя исправлять то, что не связано с проблемой. Внутренние сведения помогают сопровождению, а внешний ответ должен оставаться понятным. После любого отказа интерфейс выбирает состояние по согласованной причине, сохраняет полезный ввод и не утверждает неподтверждённый успех.','Не представляйте имена ошибок как стандартные имена HTTP.',[refs.http]),
S('Формирование успешного ответа','Подтверждение опирается на результат сохранения',P(['Сохранение завершилось','Получен номер созданной заявки'],['Собраны допустимые поля','id, project_id, student_id и status'],['Отправлен ответ','201 Created с сокращённым представлением']),
'После успешного сохранения обработчик формирует представление созданной заявки. В нём используются значения системы: установленный студент, назначенный номер и начальный статус. Не следует просто вернуть исходное тело клиента как доказательство создания. Оно не содержит серверных результатов и могло бы отразить неподдерживаемые поля. Ответ должен соответствовать действительно сохранённому состоянию и договору операции.',
'Если отправка ответа не удалась, сохранённая запись от этого не исчезает автоматически. Техническая передача и завершение операции связаны, но не являются одним событием. Поэтому клиентская неопределённость может сосуществовать с успешным сохранением. Этот факт ещё раз объясняет необходимость запрета повтора и чтения своих заявок. Дальше рассмотрим внутреннюю работу с базой: от простого чтения до почти одновременных обращений.','Отметьте подтверждение базы перед ответом.',[refs.http]),
S('Чтение данных','Запрос выбирает нужные строки и поля',C('SQL','SELECT id, title, is_open\nFROM projects\nWHERE id = $1;','Учебный SQL. Параметр $1 получает 17 отдельно от текста запроса.'),
'Эс-кью-эль, SQL, — язык работы с реляционными данными. SELECT выбирает указанные столбцы, FROM задаёт таблицу, WHERE ограничивает строки. В нашем коротком примере получаем сведения проекта семнадцать. Значение передают параметром, отдельно от текста команды. Это позволяет не строить команду простым склеиванием произвольного пользовательского ввода. Мы показываем назначение частей, не требуя запоминать синтаксис.',
'Если строка не найдена, это результат поиска в текущем состоянии, а не доказательство ошибки самого языка. Обработчик должен выбрать предусмотренное поведение. Чтение проекта нужно и для карточки, и для проверки создания. В разных операциях набор выбираемых полей может отличаться. Мы не получаем все данные только потому, что таблица технически доступна: запрос должен соответствовать задаче и праву пользователя.','SQL — «эс-кью-эль», SELECT — «выбрать».',[refs.sql]),
S('Добавление записи','INSERT создаёт заявку из проверенных значений',C('SQL',"INSERT INTO applications\n  (project_id, student_id, motivation, status, created_at)\nVALUES ($1, $2, $3, 'pending', CURRENT_TIMESTAMP)\nRETURNING id;",'Параметры: проект 17, установленный студент 12 и допустимая мотивация. id назначает база.'),
'INSERT добавляет строку. В перечне столбцов указано, какие значения сохраняются. Проект и мотивация взяты из проверенного содержимого, студент — из установленного сеанса. Начальное pending назначено системой. Время формируется при создании. RETURNING позволяет получить назначенный идентификатор, чтобы затем вернуть номер сто четыре в ответе. Мы не просим Анну самостоятельно выбрать этот номер.',
'Команда может встретить ограничение уникальности, если другая попытка уже заняла ту же пару. Это не должно превращаться во второй успешный результат или необработанную техническую надпись. Обработчик сопоставляет ожидаемый конфликт с договорённой причиной. При неожиданном сбое используются другие сведения для разбора. Такой подход сохраняет смысл правила и даёт интерфейсу конкретный результат. Код показан как короткий поясняющий пример, а не полная серверная программа.','RETURNING — возврат сформированного значения.',[refs.sql]),
S('Связанные данные в SQL','Соединение даёт название проекта для своей заявки',C('SQL','SELECT a.id, p.title, a.status\nFROM applications AS a\nJOIN projects AS p ON p.id = a.project_id\nWHERE a.student_id = $1;','Параметр $1 берётся из текущего пользователя: для Анны это 12.'),
'JOIN соединяет связанные строки. Короткие обозначения a и p помогают читать, из какой таблицы взято поле. Условие соединения сопоставляет номер проекта из заявки с ключом проекта. Условие WHERE ограничивает результат текущим студентом. Так Анна получает название темы рядом с собственным статусом без копирования названия в каждое обращение. Запрос выражает обе нужные идеи: связь данных и отбор.',
'Если убрать отбор по student_id, технически можно получить чужие заявки. Поэтому право доступа нельзя считать следствием одного правильного соединения. Оно должно присутствовать в обработке и выдаче. Также соединение не добавляет несуществующие записи: заявка должна уже сохраняться. Сокращённый пример выбирает только нужные здесь поля. Для даты или мотивации договор представления может включать дополнительные согласованные значения.','JOIN — «джойн», объясните сопоставление ключей.',[refs.sql]),
S('Ограничения базы','Разные ограничения защищают разные свойства данных',T(['Ограничение','Что предотвращает','Чего не доказывает'],[['PRIMARY KEY','Повтор ключа строки','Право пользователя'],['FOREIGN KEY','Ссылку на отсутствующую запись','Нужную роль пользователя'],['NOT NULL','Отсутствие обязательного значения','Допустимую длину текста'],['UNIQUE пары','Повтор студента и проекта','Открытость набора'],['CHECK статуса','Неизвестное значение','Разрешённый переход']]),
'Ограничения дополняют друг друга. Первичный ключ отличает строку, внешний поддерживает существование связанного объекта, обязательность запрещает отсутствие значения. Уникальная пара выражает правило повтора, список статусов — допустимый словарь. Ни одно из этих ограничений в одиночку не заменяет весь договор заявки. Таблица специально показывает и границу каждого средства. Это помогает не приписывать базе проверку, которую мы фактически не описали.',
'Некоторые правила можно дополнительно выразить в самой базе, если это оправдано архитектурой. В нашем объяснении важно распределить ответственность явно: обработчик проверяет пользователя и условия, а база поддерживает структурные ограничения. Если изменить это распределение в реализации, потребуется сохранить тот же наблюдаемый результат. Мы не делаем из выбранного учебного варианта универсальное требование ко всем системам.','Читайте третий столбец вместе со вторым.',[refs.constraints]),
S('Два одновременных запроса','Оба могут прочитать отсутствие заявки до первой записи',T(['Момент','Вкладка А','Вкладка Б'],[['1','Проверка: заявки нет','Проверка: заявки нет'],['2','Начинает добавление','Тоже начинает добавление'],['3','Сохраняет пару 12 и 17','Встречает ограничение той же пары'],['4','Получает успех','Получает конфликт повтора']]),
'Рассмотрим две почти одновременные попытки Анны. До добавления обе могут прочитать, что заявки ещё нет. Поэтому логика «сначала проверить отсутствие, затем вставить» сама по себе не гарантирует единственность. Между этими действиями другой запрос успевает изменить состояние. Отключение кнопки в одной вкладке тоже не управляет другой. Необходима защита согласованного сохранения, которая удерживает правило при конкурирующих обращениях.',
'На подготовленной временной таблице одна попытка сохраняет пару первой. Другая не создаёт второй строки и получает договорённый конфликт. Мы не утверждаем, что всегда победит вкладка А: буквы обозначают возможный порядок учебного примера. Важно свойство результата — одна запись на пару. Следующий слайд покажет, как интерфейс должен понять этот конфликт без ложного сообщения о потере данных.','Уточните, что порядок вкладок условный.'),
S('Уникальная пара при конкуренции','Один результат создания, один понятный конфликт',P(['Первая фиксация','Пара student_id 12 и project_id 17 занята'],['Следующая попытка','База не допускает вторую такую комбинацию'],['Ответ клиенту','409 APPLICATION_EXISTS и переход к своим заявкам']),
'Составное ограничение проверяет комбинацию при сохранении. Оно защищает правило даже тогда, когда предварительное чтение уже устарело. Сервер должен обработать ожидаемый конфликт и вернуть APPLICATION_EXISTS. Для Анны это означает, что на данный проект уже есть обращение. Она может открыть свои заявки и увидеть сохранённую запись. Повтор не превращается в независимое второе участие и не меняет мотивацию существующей заявки без отдельного правила.',
'Полезно отличать идемпотентное повторение от просто защищённой уникальности. Наш POST при повторе возвращает конфликт, а не обязательно тот же успешный ответ. Мы не вводили отдельный ключ идемпотентности. Согласованный механизм состоит из одной заявки на пару и понятной проверки результата через свой список. Этого достаточно для объяснения учебного случая без незаметного добавления новой инфраструктуры.','Идемпотентность здесь упомянута только для ограничения вывода.',[refs.constraints]),
S('Транзакция','Связанное изменение завершается целиком или отменяется',P(['Начало','Выделить связанные операции изменения'],['Проверки и запись','Выполнить действия в согласованной единице работы'],['Завершение','Подтвердить изменения либо отменить при отказе']),
'Транзакция объединяет действия с данными в единицу работы. При успешном завершении изменения фиксируются, при отказе могут быть отменены. Это помогает не оставлять частичный результат там, где шаги должны быть согласованы. Даже одна команда изменения выполняется в транзакционном контексте. Если операция включает несколько зависимых записей, их граница должна быть определена явно. Мы используем понятие, чтобы объяснить момент подтверждения сохранения.',
'Обычная транзакция сама по себе не означает, что любые два запроса перестали конкурировать. Итог зависит от ограничений, способа проверки и уровня изоляции. В нашем случае уникальная пара остаётся необходимым правилом. Для согласования закрытия проекта и подачи реализация также должна определять конкурентное поведение, например через блокировку нужной строки в общей дисциплине изменений. Мы не обещаем все эти свойства одним словом «транзакция».','Разделите атомарность и защиту от любого конкурентного изменения.',[refs.transaction]),
S('Сохранение перед подтверждением','Успешный ответ следует за фиксацией результата',P(['Изменение подготовлено','Запись ещё относится к незавершённой работе'],['Изменение зафиксировано','Система получила подтверждение завершения'],['Ответ отправлен','Клиент может показать успешную подачу']),
'COMMIT, фиксация транзакции, подтверждает завершение связанных изменений. До этого момента нельзя честно обещать клиенту устойчивый результат. Если обработка отправит успех, а затем не сможет завершить запись, Анна получит ложное подтверждение. Поэтому порядок на схеме принципиален: сначала согласованное сохранение, затем успешный ответ. В учебном примере только после этого заявка получает подтверждённый номер сто четыре для представления пользователю.',
'Но даже правильный порядок не гарантирует доставку ответа. Связь может оборваться после фиксации. Тогда система хранит заявку, а браузер ещё не знает результата. Это не нарушение транзакции: проблема находится на следующем участке пути. Такой разбор позволяет отдельно понять состояние данных и состояние обмена. Теперь пройдём весь основной путь по шагам, применяя уже введённые понятия к одной заявке.','COMMIT — «коммит», фиксация изменений.',[refs.transaction]),
S('Путь заявки: исходная форма','Перед отправкой выполнены пользовательские условия',U('Форма перед подачей','filled',{kind:'form',description:'Анна вошла, выбран проект 17, заполнен согласованный текст; заявка этой пары ещё не существует.'}),
'Начинаем полный путь заявки сто четыре с исходного состояния. Анна вошла, проект семнадцать открыт, её предыдущей заявки нет. В форме находится согласованная мотивация. Эти условия важны: иначе следующий ответ мог бы оказаться отказом. Мы не демонстрируем новую независимую успешную заявку после уже сохранённой. Это подробный повтор той же истории с более мелким техническим разбором. Номера и данные остаются неизменными.',
'Пока номер сто четыре известен нам как будущий результат подготовленного примера, но интерфейс ещё не показывает его пользователю. Он появится после сохранения. Такое разграничение точки зрения помогает ведущему не перескакивать через шаги. На экране выделены значения, которые попадут в тело запроса, а личность останется в доверенном контексте сеанса. Дальше рассмотрим отправленное сообщение.','Объявите подробный разбор той же истории, не вторую подачу.'),
S('Путь заявки: запрос','В сообщение вошли проект 17 и мотивация',C('HTTP + JSON',`POST /api/applications\nContent-Type: application/json\n\n${JSON.stringify({project_id:17,motivation},null,2)}`,'Шаг 2 полного пути. Сеанс Анны подразумевается и не заменяется полем student_id.'),
'Браузер сформировал POST на согласованный маршрут. В теле два поля. Значение project_id равно семнадцати и связано с карточкой. Мотивация совпадает с формой. Здесь нет номера заявки, потому что сервер ещё не создал запись. Нет student_id и status, поскольку клиент их не назначает. На этом шаге интерфейс показывает ожидание. Сообщение направлено серверу, но сам факт направления ещё не доказывает успешного выполнения.',
'Для чтения фрагмента достаточно назвать метод, путь и два значения. Мы не разбираем по буквам весь текст мотивации повторно: он уже был прочитан на форме. Важно проследить отсутствие искажения при переходе от экрана к данным. Если тело случайно содержит другой проект, нарушится пользовательский выбор, даже если запрос синтаксически корректен. Поэтому согласованность примера проверяется не только по коду ответа.','Чтение: метод, маршрут, проект, мотивация.'),
S('Путь заявки: установленный пользователь','Сервер определил Анну с id 12',T(['Проверяемое сведение','Источник','Результат шага'],[['Пользователь','Действующий сеанс','id 12'],['Роль','Сохранённые сведения пользователя','student'],['Свободный номер из тела','В договоре отсутствует','Не используется как личность']]),
'Сервер получил запрос и установил пользователя по действующему сеансу. Это Анна с идентификатором двенадцать и ролью student. Условие роли для подачи выполнено. Пользователь не выбирается по имени на странице и не подменяется полем в теле. Теперь обработчик может связать будущую заявку с Анной. Но к сохранению ещё рано переходить: нужно проверить проект, содержимое и отсутствие повтора.',
'Этот шаг показывает разницу между отсутствием поля в запросе и отсутствием значения в итоговой записи. student_id не передаётся как пользовательский ввод, но будет присутствовать в базе и ответе. Источником служит система. Такой же подход применяется к начальному статусу и времени, хотя их происхождение другое. Важно точно объяснить, откуда появляется каждое поле, чтобы не оставлять преподавателю скрытый переход.','Отметьте, что проверена личность и роль, но не весь запрос.'),
S('Путь заявки: проверка проекта','Проект существует и открыт для новой подачи',T(['Сведение проекта 17','Учебное значение','Вывод'],[['Наличие записи','Проект найден','Можно продолжить предметные проверки'],['is_open','true','Новый приём разрешён'],['teacher_id','7','Будущая заявка попадёт в область Ирины']]),
'Обработчик находит проект семнадцать и читает актуальные сведения. Проект существует, набор открыт. Значение teacher_id равно семи и позднее позволит Ирине получить заявку. Здесь мы не проверяем, является ли Анна преподавателем проекта: она действует как студент и не должна владеть проектом для подачи. Условие принадлежности понадобится при решении. Так проверка определяется конкретной операцией, а не механически копируется во все запросы.',
'Если набор закрыт, создание прекращается с причиной PROJECT_CLOSED. Существующие заявки сохраняются. Если проекта нет, это другой отказ. В конкурентной реализации проверка открытости и запись должны быть согласованы с закрытием проекта. На слайде показан успешный учебный путь, где состояние остаётся допустимым. Мы не делаем из одного раннего чтения гарантию на любое последующее время. Следующий шаг проверит мотивацию.','Не требуйте от студента принадлежности проекта.'),
S('Путь заявки: проверка мотивации','Одинаковое правило длины действует на форме и сервере',P(['Нормализация','Удалить пробельные символы с концов по общему правилу'],['Подсчёт','Посчитать Unicode code points'],['Диапазон','Принять от 50 до 1000 включительно'],['Результат','Учебная мотивация соответствует условию']),
'Сервер проверяет мотивацию независимо от браузерной подсказки. Сначала применяется согласованная нормализация, затем подсчёт и обе границы. Подготовленный текст про каталог мероприятий подходит. Мы не оцениваем здесь качество интереса Анны автоматически: это не согласованная интеллектуальная проверка. Сервер контролирует формальную допустимость, а Ирина позже читает содержание. Разделение важно, чтобы случайно не добавить скрытый алгоритм оценки.',
'Если мотивация слишком короткая, используется 422 с кодом MOTIVATION_LENGTH. Новая запись не создаётся, а интерфейс сохраняет введённое и показывает конкретное ограничение. Для граничных проверок используем обычные символы без неоднозначности подсчёта. Соответствие формы и сервера должно сохраняться при любом изменении правила. Иначе человек выполнит видимую инструкцию, но получит необъяснимый отказ. Дальше можно перейти к сохранению допустимого обращения.','Не приписывайте серверу оценку содержательной убедительности мотивации.'),
S('Путь заявки: сохранение','Пара 12 и 17 создаётся один раз',T(['До операции','Действие','После успешной фиксации'],[['Пары 12 и 17 нет','Добавить проверенные данные','Заявка id 104'],['Номер не выбран клиентом','Назначить идентификатор','104'],['Начального статуса нет','Назначить pending','На рассмотрении'],['Время не введено Анной','Сформировать created_at','Условное время создания']]),
'Теперь выполняется сохранение. До операции заявки для пары двенадцать и семнадцать нет. Система добавляет мотивацию, ссылки, начальный статус и время. Номер сто четыре получен как результат. На этом шаге база удерживает уникальность пары. Если другая попытка уже успела сохраниться, текущая не создаст вторую строку. В нашем успешном пути фиксация завершается, и запись становится основанием для ответа.',
'Таблица показывает происхождение значений, а не четыре независимые заявки. Все строки описывают одну операцию создания. Это особенно важно для ведущего: нельзя прочитать иллюстрацию так, будто статус и время возникают в разных объектах. После фиксации сервер располагает подтверждённым результатом. Следующий шаг передаст допустимое сокращённое представление клиенту, сохраняя связь с теми же полями.','Проговорите, что все строки относятся к одной записи.'),
S('Путь заявки: успешный ответ','201 сообщает о созданной заявке 104',C('HTTP + JSON','201 Created\nLocation: /api/applications/104\nContent-Type: application/json\n\n{"id":104,"project_id":17,\n "student_id":12,"status":"pending"}','Шаг 7. Сокращённый ответ после фиксации записи.'),
'Сервер отправляет успешный ответ. Номер, проект, студент и статус совпадают с сохранённой записью. Ответ сокращён, но не противоречит полной модели. Код 201 указывает создание, а pending — этап рассмотрения. Это два разных уровня результата. Один относится к выполнению операции, другой к жизненному пути заявки. Поэтому интерфейс может одновременно показать «Заявка сохранена» и «На рассмотрении» без противоречия.',
'Если код успешно получен, браузер имеет основание обновить представление. Если ответ потерян, этого основания у него пока нет, хотя операция завершилась. Мы сохраняем различие и не меняем задним числом состояние базы из-за отсутствия сообщения в окне Анны. На четвёртом вебинаре именно этот разрыв станет подготовленным инцидентом. Сейчас продолжим основной путь, в котором ответ дошёл.','Покажите два уровня: создание и рассмотрение.',[refs.http]),
S('Путь заявки: обновление интерфейса','Подтверждение отражает полученные серверные сведения',U('Заявка сохранена','success',{message:'Заявка сохранена',description:'Браузер получил 201, показал заявку 104, проект 17 и состояние «На рассмотрении».'}),
'Браузер прочитал ответ и переключил форму в подтверждение. Пользователь видит номер сто четыре и состояние ожидания решения. Эти значения взяты из результата системы, а не придуманы локально. Текст мотивации больше не является единственным местом сведений: есть сохранённая запись. Анна может перейти в свои заявки. Это завершает критерий подачи, но не весь процесс рассмотрения. Действие Ирины произойдёт позже.',
'При обновлении важно не показать неподтверждённое одобрение или новую заявку с другим номером. Подготовленный макет демонстрирует ровно то, что поддерживает ответ. Если программа использует дополнительное чтение для обновления списка, оно тоже должно учитывать текущего пользователя. Мы не требуем конкретной библиотеки управления интерфейсом. Для курса существенна причинная цепочка от подтверждённого сохранения к понятной надписи.','Не добавляйте несуществующие поля ответа.'),
S('Путь заявки: чтение Анной','Свой список подтверждает устойчивость результата',C('HTTP + JSON','GET /api/my/applications\n\n200 OK\n[{"id":104,"project_id":17,\n  "student_id":12,"status":"pending"}]','Сокращённый результат повторного чтения Анной.'),
'Анна открывает собственный список отдельным запросом. Сервер снова устанавливает пользователя и выбирает её записи. Номер сто четыре присутствует. Это показывает, что результат не зависит только от оставшегося сообщения формы. Такую же операцию можно использовать после восстановления связи, если первый ответ не дошёл. В нашем основном пути чтение просто подтверждает сохранённые сведения. При этом оно не создаёт новую заявку.',
'Если позднее Ирина примет решение, тот же путь вернёт обновлённый статус. Условия доступа останутся прежними: Анна видит свои обращения. Мы не вводим специальную ручную передачу результата от преподавателя студенту. Общая запись и согласованные представления уже поддерживают этот обмен. Теперь посмотрим, как та же заявка попадает в область работы Ирины через принадлежность проекта.','Отметьте, что GET ничего не создаёт.'),
S('Путь заявки: чтение Ириной','Одна запись доступна преподавателю своего проекта',C('HTTP + JSON','GET /api/projects/17/applications\n\n200 OK\n[{"id":104,"project_id":17,\n  "student_id":12,"status":"pending"}]','Ирина установлена как id 7; teacher_id проекта 17 равен 7.'),
'Ирина запрашивает обращения своего проекта. После проверки права сервер возвращает заявку сто четыре. Это та же запись, а не копия студенческого результата. Поэтому её последующее решение будет видно Анне через свой список. Весь путь связывает требования первого занятия, экраны второго и обмен третьего. У каждого значения известен источник, у каждого действия — условие. Так техническая схема объясняет пользовательский результат.',
'Мы завершили подробный разбор подачи. Согласованный PATCH для решения использует уже показанную проверку текущего пользователя, проекта и pending. Дальше изменим масштаб рассмотрения: программа должна работать не только как логическая последовательность, но и в доступной среде. Для этого нужны адрес, запущенный процесс, настройки и подключение к данным. Эти элементы рассмотрим без настройки серверов в эфире.','Завершите путь одной записи перед переходом к размещению.'),
S('Локальная и рабочая среда','Одинаковая программа может иметь разные настройки и данные',T(['Среда','Назначение','Данные'],[['Локальная','Разработка и подготовленные проверки','Учебный набор'],['Рабочая','Использование ресурса по общему адресу','Рабочие записи'],['Условие перехода','Настройки согласованы отдельно','Данные не подменяются автоматически']]),
'Среда — условия, в которых запущено приложение: адреса, процессы, подключения и настройки. Локальная среда удобна разработчику для подготовки изменений. Рабочая доступна пользователям. Один и тот же исходный код может использовать разные адреса базы и режимы. Поэтому успешный запуск на одном компьютере ещё не доказывает готовность для остальных. Необходимо проверить нужную конфигурацию и фактическую доступность компонентов.',
'Учебные записи не следует автоматически считать рабочими. Перенос версии программы и перенос данных являются разными действиями. В нашем курсе все значения условные. Мы рассматриваем схему размещения, а не предоставляем готовый промышленный сервер «Проектного навигатора». Такая граница помогает честно отделять подготовленные материалы от эксплуатации. Следующий шаг объяснит, как браузер получает адрес нужного приложения.','Не переносите учебные примеры в утверждения о рабочем сервисе.'),
S('Адрес приложения','Браузеру нужен доступный сетевой узел и путь',D(['Браузер','Адрес приложения','Серверный процесс'],[['Браузер','Адрес приложения','Обращение к выбранному имени и схеме'],['Адрес приложения','Серверный процесс','Доставка к доступной точке обслуживания']]),
'Для обращения браузеру нужен адрес. В локальной среде это может быть адрес собственного компьютера с номером порта. В рабочей среде обычно используется доменное имя. Порт обозначает точку обслуживания на узле. Путь внутри адреса выбирает страницу или операцию. Эти части не следует смешивать: изменение маршрута API не означает смену всей машины, а изменение домена не обязательно меняет правила заявки.',
'Доступность адреса требует запущенного приложения и подходящей сетевой настройки. Если процесс остановлен, красивое доменное имя само по себе не создаёт ответ. Если открывается стартовая страница, это ещё не доказывает доступ к базе. Поэтому проверку размещения связывают с конкретным полезным сценарием. На следующих слайдах разложим имя, защиту соединения и серверный процесс, чтобы понять их разные обязанности.','Объясните порт как точку обслуживания, без настройки в эфире.'),
S('Доменное имя','Имя помогает найти нужный узел, но не заменяет приложение',P(['Имя','Условный projects.example.test читается человеком'],['Разрешение имени','Система доменных имён помогает определить адрес узла'],['Обращение','Браузер соединяется с точкой обслуживания']),
'Доменное имя — понятное человеку обозначение сетевого ресурса. DNS, Domain Name System, помогает сопоставлять такие имена с адресной информацией. Это отдельная служба от логики заявок. Если сопоставление недоступно или неверно, браузер может не добраться до приложения. При этом данные в базе не обязаны исчезнуть. Разделение помогает сопровождению искать причину в правильной части пути.',
'В примере используем условное имя, а не существующий адрес сервиса. Оно показывает роль домена в схеме. Для рабочего размещения также учитывают управление именем и сертификатом. Мы не даём пошаговую инструкцию регистрации у конкретного поставщика, потому что задача курса — проектное понимание. Дальше посмотрим, что добавляет защищённое соединение и каких свойств оно само по себе не гарантирует.','DNS — «ди-эн-эс», расшифруйте перед сокращением.'),
S('HTTPS','Защищённое соединение дополняет правила приложения',T(['Средство','Что обеспечивает','Чего не заменяет'],[['TLS в HTTPS','Защиту обмена и проверку стороны по принятой модели сертификатов','Правильность бизнес-правил'],['Серверная авторизация','Право Анны или Ирины на действие','Защиту сетевой передачи'],['Ограничения базы','Согласованность записей','Проверку сетевого сертификата']]),
'Эйч-ти-ти-пи-эс, HTTPS, использует защищённое соединение с TLS. Оно помогает защитить передаваемые данные и проверить сервер в рамках модели сертификатов. Но замок в браузере не означает, что программа правильно проверяет роль или не создаёт дубликаты. Эти свойства относятся к другим частям проекта. Поэтому защищённую передачу включают в схему, не приписывая ей решение всех задач надёжности и доступа.',
'Для нашего пути мотивация и сведения пользователя передаются по защищённому соединению в рабочем размещении. Затем сервер всё равно применяет правила. Если пользователь не имеет права на чужую заявку, HTTPS не делает такое действие допустимым. Сопровождение должно также понимать ошибки сертификата как отдельную причину недоступности. Мы ограничиваемся назначением средства и не настраиваем сертификаты во время лекции.','TLS — «ти-эл-эс», не называйте HTTPS гарантией отсутствия ошибок.',[refs.tls]),
S('Процесс сервера','Программа должна оставаться запущенной и доступной',P(['Запуск','Рабочая версия начинает принимать обращения'],['Работа','Процесс выполняет обработчики и использует настройки'],['Остановка','Новые обращения не получают обычную обработку']),
'Сервер в нашей логической схеме — роль программы. В размещении ей соответствует запущенный процесс, то есть выполняющийся экземпляр программы. Если файлы скопированы, но процесс не работает, запросы не обслуживаются. Поэтому выпуск включает запуск и проверку. При необходимости процесс перезапускают после обновления. Нужно заранее определить, как понять, что он действительно принимает обращения, и где смотреть сведения о сбое.',
'Проверка только наличия процесса недостаточна. Он может работать, но не подключаться к базе. Также стартовая страница может отдаваться отдельно от операций API. Для учебного сервиса полезно проверить получение каталога и управляемый путь заявки в подходящем наборе данных. Эти действия показывают связь компонентов. Мы не добавляем конкретный менеджер процессов или операционную систему: выбор зависит от среды и команды.','Различайте файлы программы и выполняющийся процесс.'),
S('Подключение к базе','Обработка использует отдельные параметры доступа к данным',D(['Серверный процесс','Настройки подключения','База данных'],[['Серверный процесс','Настройки подключения','Адрес и необходимые полномочия'],['Серверный процесс','База данных','Чтение и изменение через подключение']]),
'Чтобы читать проекты и сохранять заявки, сервер устанавливает подключение к базе. Ему нужны адрес, имя хранилища и подходящие полномочия. Эти сведения относятся к конфигурации среды, а не к пользовательской форме. Браузер не должен получать доступ для произвольного выполнения команд в базе. Он обращается к согласованным операциям сервера, которые применяют правила. Такое разделение сохраняет выбранную архитектуру.',
'Если подключение недоступно, сервер не может честно подтвердить новое сохранение. Результат должен отражать сбой обработки, а технические сведения помогут сопровождению. Нельзя заменять ошибку базы сообщением о короткой мотивации. Для диагностики также полезно различать отказ подключения и нарушение ожидаемого ограничения уникальности. Один случай означает инфраструктурную проблему, другой — конфликт с текущим состоянием данных при допустимой работе базы.','Не показывайте реальные параметры или секреты подключения.'),
S('Конфигурация','Параметры среды отделяют от правил и пользовательских данных',T(['Параметр','Учебное обозначение','Назначение'],[['Адрес базы','DB_URL = значение среды','Подключение к нужному хранилищу'],['Режим','APP_ENV = production','Условия запуска'],['Адрес приложения','APP_ORIGIN = рабочий адрес','Согласованное обращение'],['Доступ','Секреты не включены в пример','Не публикуются в клиентском коде']]),
'Конфигурация задаёт параметры запуска для выбранной среды. Она позволяет использовать рабочую версию с правильной базой и адресом без редактирования пользовательской формы. В таблице показаны условные имена, а не настоящие секреты. Их значения передаются подходящим способом среды размещения. Правило длины мотивации и адрес базы имеют разный смысл: первое описывает договор проекта, второе — условия подключения.',
'Ошибка конфигурации может выглядеть как неработающее приложение, хотя код и данные сами по себе корректны. Поэтому перед выпуском проверяют наличие параметров и соответствие нужной среде. Особенно опасно случайно подключить рабочую версию к учебному хранилищу. Мы не запускаем настройку в эфире, а показываем подготовленный перечень сведений и последствий. Этого достаточно, чтобы ведущий объяснил границу между программой и средой её выполнения.','Значения параметров условные, реальные секреты не требуются.'),
S('Доступность компонентов','Рабочая страница не доказывает исправность полного пути',T(['Компонент','Признак','Ограничение вывода'],[['Страница интерфейса','Загрузилась оболочка','API может быть недоступен'],['API каталога','Получен ожидаемый список','Запись может не работать'],['База','Доступны нужные операции','Права пользователя ещё проверяются'],['Полный сценарий','Получен согласованный результат','Нужны также отрицательные проверки']]),
'Доступность нужно оценивать по составу системы. Загрузка страницы показывает, что браузер получил оболочку. Получение каталога подтверждает ещё часть пути. Создание в контролируемом сценарии проверяет запись, но не доказывает все права и ограничения. Поэтому нельзя объявить систему готовой по одному зелёному индикатору. Нужно связать признаки с тем, что они действительно подтверждают.',
'Для нашего примера критерии выпуска включат доступность компонентов и подготовленные проверки основного поведения. При отказе важно понять, где оборвался путь. Ошибка имени, соединения, процесса и базы требует разных действий. Схема размещения помогает сопоставить симптом с зависимостью, а журнал и метрики дополнят её на четвёртом занятии. Теперь перейдём к управляемому выпуску новой версии и сохранению возможности восстановления.','Читайте ограничение каждого признака вместе с самим признаком.'),
S('Выпуск версии','Изменение проходит подготовку, размещение и подтверждение',P(['Выбор версии','Известно, какой проверенный вариант выпускают'],['Подготовка','Настройки, совместимость данных и резервирование'],['Размещение','Обновление и запуск по принятому порядку'],['Подтверждение','Проверка доступности и ключевого сценария']),
'Версия обозначает конкретный набор изменений. Перед выпуском нужно знать, что проверено и что меняется. Затем готовят конфигурацию, оценивают структуру данных и способ восстановления. Размещение выполняют по понятному порядку, после чего подтверждают работу ключевого пути. Такой процесс снижает неопределённость: при проблеме можно установить, какая версия действует и что было сделано. Случайное копирование отдельных файлов затрудняет этот разбор.',
'В нашем учебном случае мы показываем порядок, а не выполняем промышленный выпуск. Ожидаемые проверки ещё не являются фактически пройденными. При работе с настоящим сервисом результат фиксируют отдельно. Полезно заранее определить, что считать неудачным выпуском и кто принимает решение о возврате. Следующие слайды раскроют настройки, изменение структуры, резервную копию и ограничения отката.','Отметьте, что схема описывает подготовленный порядок.'),
S('Подготовка настроек выпуска','Рабочая версия получает согласованную конфигурацию',T(['Проверяем','Ожидаемое состояние'],[['Среда','Выбрана рабочая, а не локальная'],['Подключение','Доступна нужная база'],['Адрес','Совпадает с опубликованным маршрутом'],['Защищённый обмен','Сертификат и HTTPS подходят адресу'],['Сведения о версии','Можно установить действующую редакцию']]),
'Подготовка настроек предотвращает часть ошибок ещё до переключения пользователей. Проверяем, что выбрана нужная среда, подключение ведёт к правильной базе, а рабочий адрес соответствует размещению. Защищённое соединение должно подходить этому имени. Полезно иметь способ установить действующую версию, иначе разбор сообщения пользователя начнётся с догадок. При этом внутренние секреты не должны появиться на публичной странице.',
'Перечень на экране — готовая памятка, а не предложение аудитории что-то настроить. Ведущий объясняет назначение каждого пункта. Нельзя считать его универсальным исчерпывающим регламентом для любого сервиса. Состав зависит от архитектуры и среды. Для «Проектного навигатора» он связывает уже введённые элементы, поэтому не добавляет внезапные внешние службы и сложные механизмы, которых нет в базовой версии.','Покажите памятку как последовательность проверки условий.'),
S('Обновление структуры данных','Новая программа должна понимать существующие записи',P(['Изменение схемы','Подготовленная операция меняет структуру хранения'],['Совместимость','Проверяется чтение старых и новых записей'],['Порядок','Обновление данных согласовано с выпуском программы']),
'Миграция схемы — управляемое изменение структуры базы. Например, при новом правиле может понадобиться дополнительное ограничение. Перед применением проверяют, соответствуют ли ему существующие записи. Если уже есть дубликаты, добавление уникальной пары потребует отдельного решения по данным. Нельзя просто объявить изменение безопасным потому, что команда короткая. Также новая и старая версии программы должны быть согласованы со структурой.',
'В нашем базовом учебном наборе схема уже соответствует правилам. Мы рассматриваем миграцию как часть будущего выпуска, не изменяя данные в эфире. Если расширение добавляет необязательное поле, это одна сложность. Если удаляет сведения, это другая и может затруднить возврат. Поэтому план изменения должен включать проверку результата и условия восстановления, а не только команду выполнения. Следующий слайд разберёт роль резервной копии.','Миграция здесь относится к схеме данных, а не к переносу пользователя.'),
S('Резервная копия','Восстановление требует пригодной копии и проверенного порядка',T(['Шаг','Назначение'],[['Подготовить копию','Сохранить состояние до рискованного изменения'],['Проверить состав','Убедиться, что нужные данные включены'],['Проверить восстановление','Установить, что копия действительно пригодна'],['Учесть время','После копии могли появиться новые записи']]),
'Резервная копия нужна для восстановления, а не для формального наличия файла. Нужно понимать, какие данные и момент она охватывает, где хранится и каким способом возвращается. Проверка восстановления показывает больше, чем успешное создание архива. Если после копии Анна подала новую заявку, возврат к старому состоянию может потерять это обращение. Поэтому восстановление требует оценки последствий и согласованного порядка.',
'У разных систем есть разные способы резервирования. Мы не выбираем конкретный режим по одной схеме. Для курса важно увидеть зависимость между выпуском, изменением данных и возможной потерей более поздних записей. Копия не заменяет совместимость программы и схемы, а старый исполняемый файл не восстанавливает удалённые сведения сам по себе. Эти ограничения объясняют, почему последний шаг выпуска требует отдельного плана возврата.','Не называйте непроверенную копию гарантией восстановления.',[refs.backup]),
S('Возврат версии и передача в сопровождение','План восстановления учитывает программу, схему и новые данные',P(['Решение о возврате','Известен признак неудачного выпуска'],['Проверка совместимости','Предыдущая программа работает с текущими данными'],['Восстановление','Учитываются изменения схемы и новые записи'],['Передача','Зафиксированы версия, адреса проверки и порядок разбора']),
'Откат программы означает возврат к предыдущей версии, но не обязательно возврат данных. Если схема изменилась несовместимо, старый код может перестать работать. Если восстановить старую копию базы, можно потерять более поздние обращения. Поэтому план восстановления оценивает все части вместе. После успешного выпуска в сопровождение передают действующую версию, способ проверки и сведения, необходимые для поиска причины сбоя.',
'Мы разобрали, как система выполняет запрос. Теперь необходимо определить, как обнаружить неправильное поведение, найти причину сбоя и понять, какие изменения принесут пользу. На четвёртом вебинаре свяжем требования с проверками, наблюдением, аналитикой и расширениями. Там же вернёмся к случаю сохранённой заявки, чей ответ не дошёл до Анны, и разберём его по подготовленным сведениям.','Не обещайте, что старый код автоматически вернёт старые данные.')
];
